import{_ as t,a,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Compare","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/compare/index.md","filePath":"api/graphql-api/shop/compare/index.md","lastUpdated":1787290888000}'),i={name:"api/graphql-api/shop/compare/index.md"};function d(p,e,s,c,h,n){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="compare" tabindex="-1">Compare <a class="header-anchor" href="#compare" aria-label="Permalink to &quot;Compare&quot;">​</a></h1><p>The Compare menu lets a signed-in customer build a side-by-side comparison list of products. A client uses it to power the &quot;add to compare&quot; action and the compare page.</p><h2 id="when-you-use-it" tabindex="-1">When you use it <a class="header-anchor" href="#when-you-use-it" aria-label="Permalink to &quot;When you use it&quot;">​</a></h2><p>The compare list is per-customer. A customer can add a product to the list, list everything in it, view one item, remove an item, or clear the whole list at once. Compare is a customer feature — it is not available to guests.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List the comparison</td><td><a href="/api/graphql-api/shop/queries/get-compare-items.html"><code>compareItems</code></a></td><td>Every product the customer has added, each with its full product detail.</td></tr><tr><td>View one entry</td><td><a href="/api/graphql-api/shop/queries/get-compare-item.html"><code>compareItem</code></a></td><td>A single comparison entry.</td></tr><tr><td>Add a product</td><td><a href="/api/graphql-api/shop/mutations/create-compare-item.html"><code>createCompareItem</code></a></td><td>Put a product on the comparison list.</td></tr><tr><td>Remove a product</td><td><a href="/api/graphql-api/shop/mutations/delete-compare-item.html"><code>deleteCompareItem</code></a></td><td>Drop one product from the list.</td></tr><tr><td>Clear the list</td><td><a href="/api/graphql-api/shop/mutations/delete-all-compare-items.html"><code>createDeleteAllCompareItems</code></a></td><td>Remove every product in one call.</td></tr></tbody></table><p>Each entry carries the whole <code>product</code> object, so a compare table can be rendered from one request — there is no need to fetch each product separately. Catalog products also carry an <code>isInCompare</code> flag, which lets a listing page show the added state without reading this list.</p><p>All Compare operations require a customer Bearer token — see <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',8)]))}const u=t(i,[["render",d]]);export{m as __pageData,u as default};
